// static const uint8_t test_jpeg_data[]  __attribute__((used, section(".rodata"))) = {0};
static const size_t test_jpeg_size = sizeof(test_jpeg_data);
#endif

static int lua_experiment_send_grayscale(lua_State *L)
{
    /* Full FOV capture: 720px sensor → scale=3 (1/8) → 90x90 → upscale to 96x96
     * Memory budget:
     *   - JPEG buffer: 64KB
     *   - Temp buffer (90x90): 8KB
     *   - Output buffer (96x96): 9KB
     *   - Peak total: ~81KB - fits in 256KB RAM
     */
    const uint16_t CAPTURE_SIZE = 720;    /* Full sensor FOV */
    const uint16_t SCALED_SIZE = 90;      /* After TJpgDec scale=3 (720/8=90) */
    const uint16_t OUTPUT_SIZE = 96;      /* Final ML input size */
    const size_t MAX_JPEG_SIZE = 25 * 1024;   /*~ 25 KB estimation */
    const size_t CHUNK_SIZE = 200;        /* BLE MTU friendly chunk size */
    const size_t READ_CHUNK_SIZE = 512;   /* Chunk size for reading JPEG from camera */

    char str_buf[128];
    size_t jpeg_size = 0;
    uint16_t actual_width, actual_height;
    int result;



    // LOG the available heap
    // TODO: 
    extern char __heap_start;
    extern char __heap_end;

    size_t heap_total = (size_t)(&__heap_end) - (size_t)(&__heap_start);
    struct mallinfo mi = mallinfo();

    size_t heap_free = heap_total - mi.uordblks;
    LOG("Heap: total=%u, used=%u, free=%u", heap_total, mi.uordblks, heap_free);
    size_t unclaimed = heap_total - mi.arena;
    LOG("Unclaimed: %u, Free blocks: %u (fragmented)", unclaimed, mi.fordblks);

    /* Allocate buffers */
    uint8_t *jpeg_buffer = malloc(MAX_JPEG_SIZE);

    LOG("Allocated JPEG buffer at %p", jpeg_buffer);
    mi = mallinfo();
    heap_free = heap_total - mi.uordblks;
    LOG("Heap: total=%u, used=%u, free=%u", heap_total, mi.uordblks, heap_free);

    uint8_t *temp_buffer = malloc(SCALED_SIZE * SCALED_SIZE);  /* 90x90 = 8KB */

    LOG("Allocated temp buffer at %p", temp_buffer);
    mi = mallinfo();
    heap_free = heap_total - mi.uordblks;
    LOG("Heap: total=%u, used=%u, free=%u", heap_total, mi.uordblks, heap_free);

    uint8_t *gray_buffer = malloc(OUTPUT_SIZE * OUTPUT_SIZE);  /* 96x96 = 9KB */

    LOG("Allocated gray buffer at %p", gray_buffer);
    mi = mallinfo();
    heap_free = heap_total - mi.uordblks;
    LOG("Heap: total=%u, used=%u, free=%u", heap_total, mi.uordblks, heap_free);

    if (!jpeg_buffer || !temp_buffer || !gray_buffer) {
        if (jpeg_buffer) free(jpeg_buffer);
        if (temp_buffer) free(temp_buffer);
        if (gray_buffer) free(gray_buffer);
        luaL_error(L, "allocation failed");
        return 0;
    }

    memset(jpeg_buffer, 0, MAX_JPEG_SIZE);
    memset(temp_buffer, 0, SCALED_SIZE * SCALED_SIZE);
    memset(gray_buffer, 0, OUTPUT_SIZE * OUTPUT_SIZE);

#ifdef DEV_KIT_BUILD
    /* Use test image data instead of camera capture */
    /* Test image is 720x720 - use same flow as real camera:
     * scale=3 (1/8) → 90x90 → upscale to 96x96 */

    free(jpeg_buffer);  /* Not needed for dev kit */

    /* Decode with scale=3 (1/8): 720 → 90 */
    result = jpeg_decode_grayscale_scaled(test_jpeg_data, test_jpeg_size,
                                           temp_buffer, SCALED_SIZE, SCALED_SIZE,
                                           &actual_width, &actual_height,
                                           3, false);  /* scale=3 (1/8), no rotation */

    if (result != 0) {
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "decode failed: %d", result);
        return 0;
    }

    LOG("DEV_KIT: decoded %dx%d, upscaling to %dx%d", actual_width, actual_height, OUTPUT_SIZE, OUTPUT_SIZE);

    /* Upscale 90x90 to 96x96 with rotation */
    upscale_90_to_96_with_rotation(temp_buffer, gray_buffer);
    free(temp_buffer);

    /* Debug: analyze pixel values */
    {
        uint8_t min_val = 255, max_val = 0;
        uint32_t sum = 0;
        for (int i = 0; i < OUTPUT_SIZE * OUTPUT_SIZE; i++) {
            if (gray_buffer[i] < min_val) min_val = gray_buffer[i];
            if (gray_buffer[i] > max_val) max_val = gray_buffer[i];
            sum += gray_buffer[i];
        }
        LOG("DEV_KIT decode: min=%d max=%d avg=%d", min_val, max_val, sum / (OUTPUT_SIZE * OUTPUT_SIZE));
    }

    /* Override dimensions with actual output size */
    actual_width = OUTPUT_SIZE;
    actual_height = OUTPUT_SIZE;
#else
    /* ===== Step 0: Wake up camera (ensure not in power save) ===== */
    lua_getglobal(L, "frame");
    if (!lua_istable(L, -1)) {
        lua_pop(L, 1);
        free(jpeg_buffer);
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "frame global not found");
        return 0;
    }
    lua_getfield(L, -1, "camera");
    if (!lua_istable(L, -1)) {
        lua_pop(L, 2);
        free(jpeg_buffer);
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "frame.camera not found");
        return 0;
    }
    lua_getfield(L, -1, "power_save");
    if (lua_isfunction(L, -1)) {
        lua_pushboolean(L, 0);  /* power_save(false) to wake camera */
        if (lua_pcall(L, 1, 0, 0) != LUA_OK) {
            lua_pop(L, 3);
        }
    } else {
        lua_pop(L, 1);  /* Pop non-function value */
    }
    lua_pop(L, 2);  /* Pop camera, frame */
    
    /* Delay after wake-up for camera sensor initialization */
    nrfx_systick_delay_ms(100);

    /* ===== Step 1: Auto-adjust camera parameters (multiple iterations) ===== */
    /* Run auto-exposure loop similar to the example apps.
     * The algorithm needs multiple iterations to converge, with delays between
     * to allow the camera sensor to update its metering registers.
     * Reduced to 5 iterations to avoid watchdog timeout (~500ms total)
     */
    const int AUTO_ITERATIONS = 5;
    for (int i = 0; i < AUTO_ITERATIONS; i++) {
        lua_getglobal(L, "frame");
        lua_getfield(L, -1, "camera");
        lua_getfield(L, -1, "auto");
        if (!lua_isfunction(L, -1)) {
            lua_pop(L, 3);
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "frame.camera.auto not found");
            return 0;
        }
        /* Use recommended auto settings from camera.c defaults:
         * metering=CENTER_WEIGHTED, exposure=0.1, exposure_speed=0.45 */
        lua_newtable(L);
        if (lua_pcall(L, 1, 1, 0) != LUA_OK) {
            const char *err = lua_tostring(L, -1);
            lua_pop(L, 3);  /* Pop error, camera, frame */
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "camera.auto failed: %s", err);
            return 0;
        }
        lua_pop(L, 3);  /* Pop result, camera, frame */
        
        /* Delay between auto iterations for camera to update metering.
         * 100ms matches the frame.sleep(0.1) in the example Lua apps. */
        nrfx_systick_delay_ms(100);
        reload_watchdog(NULL, NULL);  /* Feed watchdog during long operation */
    }

    /* ===== Step 2: Capture image ===== */
    /* Call frame.camera.capture({resolution=CAPTURE_SIZE, quality="HIGH"}) 
     * Using HIGH quality for better JPEG fidelity at low resolution */
    lua_getglobal(L, "frame");
    lua_getfield(L, -1, "camera");
    lua_getfield(L, -1, "capture");
    if (!lua_isfunction(L, -1)) {
        lua_pop(L, 3);
        free(jpeg_buffer);
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "frame.camera.capture not found");
        return 0;
    }
    lua_newtable(L);
    lua_pushinteger(L, CAPTURE_SIZE);
    lua_setfield(L, -2, "resolution");
    lua_pushstring(L, "HIGH");
    lua_setfield(L, -2, "quality");
    if (lua_pcall(L, 1, 0, 0) != LUA_OK) {
        const char *err = lua_tostring(L, -1);
        lua_pop(L, 3);  /* Pop error, camera, frame */
        free(jpeg_buffer);
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "camera.capture failed: %s", err);
        return 0;
    }
    lua_pop(L, 2);  /* Pop camera, frame */

    /* ===== Step 3: Wait for image to be ready ===== */
    uint32_t timeout = 1000000;
    uint32_t wdt_counter = 0;
    bool ready = false;
    while (timeout-- && !ready) {
        lua_getglobal(L, "frame");
        lua_getfield(L, -1, "camera");
        lua_getfield(L, -1, "image_ready");
        if (lua_pcall(L, 0, 1, 0) != LUA_OK) {
            const char *err = lua_tostring(L, -1);
            lua_pop(L, 3);  /* Pop error, camera, frame */
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "camera.image_ready failed: %s", err);
            return 0;
        }
        ready = lua_toboolean(L, -1);
        lua_pop(L, 3);  /* Pop result, camera, frame */
        if (!ready) {
            nrfx_systick_delay_us(10);
            /* Feed watchdog every 10000 iterations (~100ms) */
            if (++wdt_counter >= 10000) {
                reload_watchdog(NULL, NULL);
                wdt_counter = 0;
            }
        }
    }

    if (!ready) {
        free(jpeg_buffer);
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "capture timeout");
        return 0;
    }

    /* ===== Step 4: Read JPEG data ===== */
    /* Call frame.camera.read(READ_CHUNK_SIZE) in a loop until nil */
    jpeg_size = 0;
    while (jpeg_size < MAX_JPEG_SIZE) {
        lua_getglobal(L, "frame");
        lua_getfield(L, -1, "camera");
        lua_getfield(L, -1, "read");
        lua_pushinteger(L, READ_CHUNK_SIZE);
        if (lua_pcall(L, 1, 1, 0) != LUA_OK) {
            const char *err = lua_tostring(L, -1);
            lua_pop(L, 3);  /* Pop error, camera, frame */
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "camera.read failed: %s", err);
            return 0;
        }

        if (lua_isnil(L, -1)) {
            lua_pop(L, 3);  /* Pop nil, camera, frame */
            break;
        }

        size_t chunk_len;
        const char *chunk = lua_tolstring(L, -1, &chunk_len);
        if (jpeg_size + chunk_len > MAX_JPEG_SIZE) {
            lua_pop(L, 3);
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "JPEG too large");
            return 0;
        }
        memcpy(jpeg_buffer + jpeg_size, chunk, chunk_len);
        jpeg_size += chunk_len;
        lua_pop(L, 3);  /* Pop chunk string, camera, frame */
        reload_watchdog(NULL, NULL);  /* Feed watchdog during JPEG read */
    }

    if (jpeg_size == 0) {
        free(jpeg_buffer);
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "no JPEG data received");
        return 0;
    }

    /* ===== Step 5: Decode JPEG to grayscale with 1/8 scaling ===== */
    /* The JPEG from camera.read() is complete (header + data + footer)
     * Use scale=3 (1/8) to decode 720px → 90x90, then upscale to 96x96
     */
    reload_watchdog(NULL, NULL);  /* Feed watchdog before decode */
    result = jpeg_decode_grayscale_scaled(jpeg_buffer, jpeg_size,
                                           temp_buffer, SCALED_SIZE, SCALED_SIZE,
                                           &actual_width, &actual_height,
                                           3, false);  /* scale=3 (1/8), no rotation */

    free(jpeg_buffer);

    if (result != 0) {
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "decode failed: %d", result);
        return 0;
    }

    /* ===== Step 6: Upscale 90x90 to 96x96 with 90° CCW rotation ===== */
    reload_watchdog(NULL, NULL);  /* Feed watchdog before upscale */
    upscale_90_to_96_with_rotation(temp_buffer, gray_buffer);
    free(temp_buffer);

    /* Override dimensions with final output size */
    actual_width = OUTPUT_SIZE;
    actual_height = OUTPUT_SIZE;
#endif /* !DEV_KIT_BUILD */

    /* Send header with dimensions */
    snprintf(str_buf, sizeof(str_buf), "GRAY:%d,%d,%d\n",
             actual_width, actual_height, actual_width * actual_height);
    // bluetooth_send_data((uint8_t *)str_buf, strlen(str_buf));

    /* Small delay to let header be received */
    nrfx_systick_delay_ms(50);

    /* Send grayscale data in chunks */
    size_t total_bytes = actual_width * actual_height;
    size_t offset = 0;
    
    /* Allocate chunk buffer with space for data flag byte */
    uint8_t *chunk_buffer = malloc(CHUNK_SIZE + 1);
    if (!chunk_buffer) {
        free(gray_buffer);
        luaL_error(L, "chunk allocation failed");
        return 0;
    }
    chunk_buffer[0] = 0x01;  /* Data flag - same as frame.bluetooth.send() uses */
    
    while (offset < total_bytes) {
        size_t chunk = (total_bytes - offset > CHUNK_SIZE) ? CHUNK_SIZE : (total_bytes - offset);
        memcpy(chunk_buffer + 1, gray_buffer + offset, chunk);
        bluetooth_send_data(chunk_buffer, chunk + 1);
        offset += chunk;
        nrfx_systick_delay_ms(20);  /* Allow BLE to transmit */
        reload_watchdog(NULL, NULL);  /* Feed watchdog during transmission */
    }
    
    /* Send end marker: 0x01 flag + unique pattern that won't appear in grayscale data */
    nrfx_systick_delay_ms(100);  /* Longer delay to ensure all chunks transmitted */
    uint8_t end_marker[5] = {0x01, 0xFF, 0xFF, 0x00, 0x00};  /* Flag + pattern */
    bluetooth_send_data(end_marker, 5);
    
    free(chunk_buffer);

    free(gray_buffer);

    lua_pushinteger(L, total_bytes);
    return 1;
}

/**
 * Draw detection overlay on Frame display after FOMO inference
 * Maps camera FOV to display FOV with edge indicators for peripheral detections.
 *
 * Camera FOV (~56°) is wider than display FOV (~20°). The display shows the center
 * portion of what the camera sees. Detections outside the display FOV are shown
 * as vertical lines on the left/right edges.
 *
 * @param output_grid Pointer to 192-byte int8 output grid (8x8x3)
 */
static void draw_detection_overlay(const int8_t *output_grid)
{
    const int8_t DETECTION_THRESHOLD = -50;

    /* Display dimensions */
    const uint16_t DISPLAY_W = 640;
    const uint16_t DISPLAY_H = 400;

    /*
     * FOV mapping: Camera sees ~56°, display shows ~20° (center portion)
     * The 8x8 grid covers the full camera FOV.
     * Display FOV corresponds to roughly the center 2-3 cells.
     *
     * We map grid cells to display as follows:
     * - Center cells (2-5) map to the full display width
     * - Edge cells (0-1, 6-7) trigger edge indicators
     */
    const int CENTER_START = 2;  /* First grid column shown on display */
    const int CENTER_END = 5;    /* Last grid column shown on display */
    const int CENTER_COLS = CENTER_END - CENTER_START + 1;  /* 4 columns */

    /* Vertical: use full grid since display vertical FOV is similar */
    const uint16_t CELL_HEIGHT = DISPLAY_H / FOMO_GRID_SIZE;  /* 50 px per cell */

    /* Sprite size */
    const uint16_t SPRITE_SIZE = 24;

    /* Edge indicator dimensions */
    const uint16_t LINE_WIDTH = 12;
    const uint16_t LINE_HEIGHT = 80;

    /* Palette color indices */
    const uint8_t BEER_COLOR = 3;       /* RED */
    const uint8_t CAN_COLOR = 14;       /* SKYBLUE */

    /* 24x24 filled circle sprite (2-color, 1-bit): 576 pixels / 8 = 72 bytes */
    static const uint8_t dot_sprite[72] = {
        0x00, 0x7E, 0x00,  /* Row 0 */
        0x01, 0xFF, 0x80,  /* Row 1 */
        0x07, 0xFF, 0xE0,  /* Row 2 */
        0x0F, 0xFF, 0xF0,  /* Row 3 */
        0x1F, 0xFF, 0xF8,  /* Row 4 */
        0x3F, 0xFF, 0xFC,  /* Row 5 */
        0x3F, 0xFF, 0xFC,  /* Row 6 */
        0x7F, 0xFF, 0xFE,  /* Row 7 */
        0x7F, 0xFF, 0xFE,  /* Row 8 */
        0xFF, 0xFF, 0xFF,  /* Row 9 */
        0xFF, 0xFF, 0xFF,  /* Row 10 */
        0xFF, 0xFF, 0xFF,  /* Row 11 */
        0xFF, 0xFF, 0xFF,  /* Row 12 */
        0xFF, 0xFF, 0xFF,  /* Row 13 */
        0xFF, 0xFF, 0xFF,  /* Row 14 */
        0x7F, 0xFF, 0xFE,  /* Row 15 */
        0x7F, 0xFF, 0xFE,  /* Row 16 */
        0x3F, 0xFF, 0xFC,  /* Row 17 */
        0x3F, 0xFF, 0xFC,  /* Row 18 */
        0x1F, 0xFF, 0xF8,  /* Row 19 */
        0x0F, 0xFF, 0xF0,  /* Row 20 */
        0x07, 0xFF, 0xE0,  /* Row 21 */
        0x01, 0xFF, 0x80,  /* Row 22 */
        0x00, 0x7E, 0x00,  /* Row 23 */
    };
    const size_t DOT_SPRITE_SIZE = 72;

    /* Track edge detections (store best Y position for each side) */
    uint8_t left_edge_color = 0;
    uint8_t right_edge_color = 0;
    int16_t left_edge_y = -1;
    int16_t right_edge_y = -1;

    for (int gy = 0; gy < FOMO_GRID_SIZE; gy++) {
        for (int gx = 0; gx < FOMO_GRID_SIZE; gx++) {
            int idx = (gy * FOMO_GRID_SIZE + gx) * FOMO_NUM_CLASSES;

            int8_t beer_score = output_grid[idx + 1];
            int8_t can_score = output_grid[idx + 2];

            uint8_t color = 0;
            if (beer_score > DETECTION_THRESHOLD && beer_score >= can_score) {
                color = BEER_COLOR;
            } else if (can_score > DETECTION_THRESHOLD) {
                color = CAN_COLOR;
            }

            if (color == 0) continue;

            /* Calculate Y position (same for all cases) */
            int16_t py = gy * CELL_HEIGHT + (CELL_HEIGHT - SPRITE_SIZE) / 2;
            if (py < 0) py = 0;
            if (py > DISPLAY_H - SPRITE_SIZE) py = DISPLAY_H - SPRITE_SIZE;

            if (gx >= CENTER_START && gx <= CENTER_END) {
                /* Detection is within display FOV - draw dot */
                /* Map center columns (2-5) to full display width */
                int rel_x = gx - CENTER_START;  /* 0 to 3 */
                uint16_t cell_width = DISPLAY_W / CENTER_COLS;
                int16_t px = rel_x * cell_width + (cell_width - SPRITE_SIZE) / 2;

                if (px < 0) px = 0;
                if (px > DISPLAY_W - SPRITE_SIZE) px = DISPLAY_W - SPRITE_SIZE;

                uint8_t meta[8] = {
                    (uint8_t)(px >> 8), (uint8_t)(px & 0xFF),
                    (uint8_t)(py >> 8), (uint8_t)(py & 0xFF),
                    0, SPRITE_SIZE,
                    2,
                    color
                };

                uint8_t *payload = malloc(8 + DOT_SPRITE_SIZE);
                if (payload) {
                    memcpy(payload, meta, 8);
                    memcpy(payload + 8, dot_sprite, DOT_SPRITE_SIZE);
                    spi_write(FPGA, 0x12, payload, 8 + DOT_SPRITE_SIZE);
                    free(payload);
                }
            } else if (gx < CENTER_START) {
                /* Left of display FOV - mark for edge indicator */
                if (left_edge_color == 0 || color == BEER_COLOR) {
                    left_edge_color = color;
                    left_edge_y = py;
                }
            } else {
                /* Right of display FOV - mark for edge indicator */
                if (right_edge_color == 0 || color == BEER_COLOR) {
                    right_edge_color = color;
                    right_edge_y = py;
                }
            }
        }
    }

    /* Draw left edge indicator line */
    if (left_edge_color != 0) {
        uint16_t px = 0;
        uint16_t py = (left_edge_y >= 0) ? (uint16_t)left_edge_y : (DISPLAY_H - LINE_HEIGHT) / 2;
        if (py > DISPLAY_H - LINE_HEIGHT) py = DISPLAY_H - LINE_HEIGHT;

        /* Line sprite: 12 wide x 80 tall, 1-bit = 2 bytes per row */
        size_t line_bytes = LINE_HEIGHT * 2;
        uint8_t *line_data = malloc(line_bytes);
        if (line_data) {
            memset(line_data, 0xFF, line_bytes);

            uint8_t meta[8] = {
                (uint8_t)(px >> 8), (uint8_t)(px & 0xFF),
                (uint8_t)(py >> 8), (uint8_t)(py & 0xFF),
                0, LINE_WIDTH,
                2,
                left_edge_color
            };

            uint8_t *payload = malloc(8 + line_bytes);
            if (payload) {
                memcpy(payload, meta, 8);
                memcpy(payload + 8, line_data, line_bytes);
                spi_write(FPGA, 0x12, payload, 8 + line_bytes);
                free(payload);
            }
            free(line_data);
        }
    }

    /* Draw right edge indicator line */
    if (right_edge_color != 0) {
        uint16_t px = DISPLAY_W - LINE_WIDTH;
        uint16_t py = (right_edge_y >= 0) ? (uint16_t)right_edge_y : (DISPLAY_H - LINE_HEIGHT) / 2;
        if (py > DISPLAY_H - LINE_HEIGHT) py = DISPLAY_H - LINE_HEIGHT;

        size_t line_bytes = LINE_HEIGHT * 2;
        uint8_t *line_data = malloc(line_bytes);
        if (line_data) {
            memset(line_data, 0xFF, line_bytes);

            uint8_t meta[8] = {
                (uint8_t)(px >> 8), (uint8_t)(px & 0xFF),
                (uint8_t)(py >> 8), (uint8_t)(py & 0xFF),
                0, LINE_WIDTH,
                2,
                right_edge_color
            };

            uint8_t *payload = malloc(8 + line_bytes);
            if (payload) {
                memcpy(payload, meta, 8);
                memcpy(payload + 8, line_data, line_bytes);
                spi_write(FPGA, 0x12, payload, 8 + line_bytes);
                free(payload);
            }
            free(line_data);
        }
    }

    /* Swap frame buffers to display */
    spi_write(FPGA, 0x14, NULL, 0);
}

/**
 * Run FOMO object detection model and send results via Bluetooth
 * Usage: frame.experiment.run_object_detection_model()
 * Returns: number of bytes sent
 *
 * Protocol:
 *   [IMAGE DATA]     4096 bytes (21 chunks × 200 bytes + remainder)
 *   [SEPARATOR]      0x01 0xFE 0xFE
 *   [PREDICTIONS]    192 bytes (1 chunk)
 *   [END MARKER]     0x01 0xFF 0xFF 0x00 0x00
 */
static int lua_experiment_run_object_detection(lua_State *L)
{
    /* Full FOV capture: 720px sensor → scale=3 (1/8) → 90x90 → downscale to 64x64
     * Memory budget:
     *   - JPEG buffer: 25KB (720x720 JPEG)
     *   - Temp buffer (90x90): 8KB
     *   - Output buffer (64x64): 4KB
     *   - Tensor arena: ~135KB (allocated statically in tflm_wrapper.cc)
     *   - Output grid: 192 bytes (stack)
     *   - Peak total: ~172KB
     */
    const uint16_t CAPTURE_SIZE = 720;    /* Full sensor FOV */
    const uint16_t SCALED_SIZE = 90;      /* After TJpgDec scale=3 (720/8=90) */
    const uint16_t OUTPUT_SIZE = 64;      /* ML input size (64x64) */
    const size_t MAX_JPEG_SIZE = 25 * 1024;   /* 25KB for 720x720 */
    const size_t CHUNK_SIZE = 200;        /* BLE MTU friendly chunk size */
    const size_t READ_CHUNK_SIZE = 512;   /* Chunk size for reading JPEG from camera */

    size_t jpeg_size = 0;
    uint16_t actual_width, actual_height;
    int result;

    /* Check if FOMO model is initialized */
    if (!fomo_is_initialized()) {
        luaL_error(L, "FOMO model not initialized");
        return 0;
    }

    /* Allocate buffers */
    uint8_t *jpeg_buffer = malloc(MAX_JPEG_SIZE);
    uint8_t *temp_buffer = malloc(SCALED_SIZE * SCALED_SIZE);  /* 90x90 = 8KB */
    uint8_t *gray_buffer = malloc(OUTPUT_SIZE * OUTPUT_SIZE);  /* 64x64 = 4KB */
    if (!jpeg_buffer || !temp_buffer || !gray_buffer) {
        if (jpeg_buffer) free(jpeg_buffer);
        if (temp_buffer) free(temp_buffer);
        if (gray_buffer) free(gray_buffer);
        luaL_error(L, "allocation failed");
        return 0;
    }

    memset(jpeg_buffer, 0, MAX_JPEG_SIZE);
    memset(temp_buffer, 0, SCALED_SIZE * SCALED_SIZE);
    memset(gray_buffer, 0, OUTPUT_SIZE * OUTPUT_SIZE);

#ifdef DEV_KIT_BUILD
    /* Use test image data instead of camera capture */
    free(jpeg_buffer);  /* Not needed for dev kit */

    /* Decode test image (720x720) with scale=3 (1/8) → 90x90, then downscale to 64x64 */
    result = jpeg_decode_grayscale_scaled(test_jpeg_data, test_jpeg_size,
                                           temp_buffer, SCALED_SIZE, SCALED_SIZE,
                                           &actual_width, &actual_height,
                                           3, false);  /* scale=3 (1/8), no rotation */

    if (result != 0) {
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "decode failed: %d", result);
        return 0;
    }

    LOG("DEV_KIT: decoded %dx%d, downscaling to %dx%d", actual_width, actual_height, OUTPUT_SIZE, OUTPUT_SIZE);

    /* Bilinear downscale 90x90 to 64x64 (no rotation for test image) */
    {
        const float scale = (float)SCALED_SIZE / (float)OUTPUT_SIZE;
        for (int dy = 0; dy < OUTPUT_SIZE; dy++) {
            for (int dx = 0; dx < OUTPUT_SIZE; dx++) {
                float sx = dx * scale;
                float sy = dy * scale;

                int x0 = (int)sx;
                int y0 = (int)sy;
                int x1 = (x0 + 1 < SCALED_SIZE) ? x0 + 1 : x0;
                int y1 = (y0 + 1 < SCALED_SIZE) ? y0 + 1 : y0;

                float fx = sx - x0;
                float fy = sy - y0;

                float v00 = temp_buffer[y0 * SCALED_SIZE + x0];
                float v10 = temp_buffer[y0 * SCALED_SIZE + x1];
                float v01 = temp_buffer[y1 * SCALED_SIZE + x0];
                float v11 = temp_buffer[y1 * SCALED_SIZE + x1];

                float v = v00 * (1-fx) * (1-fy) + v10 * fx * (1-fy) +
                          v01 * (1-fx) * fy + v11 * fx * fy;

                gray_buffer[dy * OUTPUT_SIZE + dx] = (uint8_t)(v + 0.5f);
            }
        }
    }
    free(temp_buffer);

    actual_width = OUTPUT_SIZE;
    actual_height = OUTPUT_SIZE;
#else
    /* ===== Step 0: Wake up camera (ensure not in power save) ===== */
    lua_getglobal(L, "frame");
    if (!lua_istable(L, -1)) {
        lua_pop(L, 1);
        free(jpeg_buffer);
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "frame global not found");
        return 0;
    }
    lua_getfield(L, -1, "camera");
    if (!lua_istable(L, -1)) {
        lua_pop(L, 2);
        free(jpeg_buffer);
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "frame.camera not found");
        return 0;
    }
    lua_getfield(L, -1, "power_save");
    if (lua_isfunction(L, -1)) {
        lua_pushboolean(L, 0);  /* power_save(false) to wake camera */
        if (lua_pcall(L, 1, 0, 0) != LUA_OK) {
            lua_pop(L, 3);
        }
    } else {
        lua_pop(L, 1);  /* Pop non-function value */
    }
    lua_pop(L, 2);  /* Pop camera, frame */

    /* Delay after wake-up for camera sensor initialization */
    nrfx_systick_delay_ms(100);

    /* ===== Step 1: Auto-adjust camera parameters (multiple iterations) ===== */
    const int AUTO_ITERATIONS = 5;
    for (int i = 0; i < AUTO_ITERATIONS; i++) {
        lua_getglobal(L, "frame");
        lua_getfield(L, -1, "camera");
        lua_getfield(L, -1, "auto");
        if (!lua_isfunction(L, -1)) {
            lua_pop(L, 3);
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "frame.camera.auto not found");
            return 0;
        }
        lua_newtable(L);
        if (lua_pcall(L, 1, 1, 0) != LUA_OK) {
            const char *err = lua_tostring(L, -1);
            lua_pop(L, 3);
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "camera.auto failed: %s", err);
            return 0;
        }
        lua_pop(L, 3);

        nrfx_systick_delay_ms(100);
        reload_watchdog(NULL, NULL);
    }

    /* ===== Step 2: Capture image ===== */
    lua_getglobal(L, "frame");
    lua_getfield(L, -1, "camera");
    lua_getfield(L, -1, "capture");
    if (!lua_isfunction(L, -1)) {
        lua_pop(L, 3);
        free(jpeg_buffer);
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "frame.camera.capture not found");
        return 0;
    }
    lua_newtable(L);
    lua_pushinteger(L, CAPTURE_SIZE);
    lua_setfield(L, -2, "resolution");
    lua_pushstring(L, "MEDIUM");
    lua_setfield(L, -2, "quality");
    if (lua_pcall(L, 1, 0, 0) != LUA_OK) {
        const char *err = lua_tostring(L, -1);
        lua_pop(L, 3);
        free(jpeg_buffer);
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "camera.capture failed: %s", err);
        return 0;
    }
    lua_pop(L, 2);

    /* ===== Step 3: Wait for image to be ready ===== */
    uint32_t timeout = 1000000;
    uint32_t wdt_counter = 0;
    bool ready = false;
    while (timeout-- && !ready) {
        lua_getglobal(L, "frame");
        lua_getfield(L, -1, "camera");
        lua_getfield(L, -1, "image_ready");
        if (lua_pcall(L, 0, 1, 0) != LUA_OK) {
            const char *err = lua_tostring(L, -1);
            lua_pop(L, 3);
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "camera.image_ready failed: %s", err);
            return 0;
        }
        ready = lua_toboolean(L, -1);
        lua_pop(L, 3);
        if (!ready) {
            nrfx_systick_delay_us(10);
            if (++wdt_counter >= 10000) {
                reload_watchdog(NULL, NULL);
                wdt_counter = 0;
            }
        }
    }

    if (!ready) {
        free(jpeg_buffer);
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "capture timeout");
        return 0;
    }

    /* ===== Step 4: Read JPEG data ===== */
    jpeg_size = 0;
    while (jpeg_size < MAX_JPEG_SIZE) {
        lua_getglobal(L, "frame");
        lua_getfield(L, -1, "camera");
        lua_getfield(L, -1, "read");
        lua_pushinteger(L, READ_CHUNK_SIZE);
        if (lua_pcall(L, 1, 1, 0) != LUA_OK) {
            const char *err = lua_tostring(L, -1);
            lua_pop(L, 3);
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "camera.read failed: %s", err);
            return 0;
        }

        if (lua_isnil(L, -1)) {
            lua_pop(L, 3);
            break;
        }

        size_t chunk_len;
        const char *chunk = lua_tolstring(L, -1, &chunk_len);
        if (jpeg_size + chunk_len > MAX_JPEG_SIZE) {
            lua_pop(L, 3);
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "JPEG too large");
            return 0;
        }
        memcpy(jpeg_buffer + jpeg_size, chunk, chunk_len);
        jpeg_size += chunk_len;
        lua_pop(L, 3);
        reload_watchdog(NULL, NULL);
    }

    if (jpeg_size == 0) {
        free(jpeg_buffer);
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "no JPEG data received");
        return 0;
    }

    /* ===== Step 5: Decode JPEG to grayscale with 1/8 scaling ===== */
    /* 720x720 with scale=3 (1/8) → 90x90 */
    reload_watchdog(NULL, NULL);

    result = jpeg_decode_grayscale_scaled(jpeg_buffer, jpeg_size,
                                           temp_buffer, SCALED_SIZE, SCALED_SIZE,
                                           &actual_width, &actual_height,
                                           3, false);  /* scale=3 (1/8), no rotation */

    free(jpeg_buffer);

    if (result != 0) {
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "decode failed: %d", result);
        return 0;
    }

    LOG("Decoded %dx%d, downscaling to %dx%d with 90 CCW rotation",
        actual_width, actual_height, OUTPUT_SIZE, OUTPUT_SIZE);

    /* ===== Step 6: Downscale 90x90 to 64x64 with 90° CCW rotation ===== */
    /* Bilinear downscale with rotation: (x, y) -> (y, SIZE-1-x) for 90° CCW */
    reload_watchdog(NULL, NULL);
    {
        const float scale = (float)SCALED_SIZE / (float)OUTPUT_SIZE;  /* 90/64 = 1.40625 */
        for (int dy = 0; dy < OUTPUT_SIZE; dy++) {
            for (int dx = 0; dx < OUTPUT_SIZE; dx++) {
                /* Map destination to source coordinates */
                float sx = dx * scale;
                float sy = dy * scale;

                int x0 = (int)sx;
                int y0 = (int)sy;
                int x1 = (x0 + 1 < SCALED_SIZE) ? x0 + 1 : x0;
                int y1 = (y0 + 1 < SCALED_SIZE) ? y0 + 1 : y0;

                float fx = sx - x0;
                float fy = sy - y0;

                /* Bilinear interpolation */
                float v00 = temp_buffer[y0 * SCALED_SIZE + x0];
                float v10 = temp_buffer[y0 * SCALED_SIZE + x1];
                float v01 = temp_buffer[y1 * SCALED_SIZE + x0];
                float v11 = temp_buffer[y1 * SCALED_SIZE + x1];

                float v = v00 * (1-fx) * (1-fy) + v10 * fx * (1-fy) +
                          v01 * (1-fx) * fy + v11 * fx * fy;

                /* Apply 90° CCW rotation: (dx, dy) -> (dy, OUTPUT_SIZE-1-dx) */
                int rx = dy;
                int ry = OUTPUT_SIZE - 1 - dx;
                gray_buffer[ry * OUTPUT_SIZE + rx] = (uint8_t)(v + 0.5f);
            }
        }
    }
    free(temp_buffer);

    actual_width = OUTPUT_SIZE;
    actual_height = OUTPUT_SIZE;
#endif /* !DEV_KIT_BUILD */

    /* ===== Step 7: Run FOMO inference ===== */
    reload_watchdog(NULL, NULL);
    int8_t output_grid[FOMO_OUTPUT_SIZE];  /* 432 bytes on stack */

    tflm_status_t infer_status = fomo_infer(gray_buffer, output_grid);
    if (infer_status != TFLM_OK) {
        free(gray_buffer);
        luaL_error(L, "FOMO inference failed");
        return 0;
    }

    LOG("FOMO inference complete");

    /* ===== Step 7.5: Display detection overlay on Frame ===== */
    draw_detection_overlay(output_grid);
    reload_watchdog(NULL, NULL);

    /* ===== Step 8: Send image data via Bluetooth ===== */
    size_t total_bytes = actual_width * actual_height;  /* 9216 */
    size_t offset = 0;

    /* Allocate chunk buffer with space for data flag byte */
    uint8_t *chunk_buffer = malloc(CHUNK_SIZE + 1);
    if (!chunk_buffer) {
        free(gray_buffer);
        luaL_error(L, "chunk allocation failed");
        return 0;
    }
    chunk_buffer[0] = 0x01;  /* Data flag */

    while (offset < total_bytes) {
        size_t chunk = (total_bytes - offset > CHUNK_SIZE) ? CHUNK_SIZE : (total_bytes - offset);
        memcpy(chunk_buffer + 1, gray_buffer + offset, chunk);
        bluetooth_send_data(chunk_buffer, chunk + 1);
        offset += chunk;
        nrfx_systick_delay_ms(20);
        reload_watchdog(NULL, NULL);
    }

    free(gray_buffer);

    /* ===== Step 9: Send separator ===== */
    nrfx_systick_delay_ms(50);
    uint8_t separator[3] = {0x01, 0xFE, 0xFE};
    bluetooth_send_data(separator, 3);

    /* ===== Step 10: Send predictions (432 bytes) ===== */
    nrfx_systick_delay_ms(50);
    offset = 0;
    while (offset < FOMO_OUTPUT_SIZE) {
        size_t chunk = (FOMO_OUTPUT_SIZE - offset > CHUNK_SIZE) ? CHUNK_SIZE : (FOMO_OUTPUT_SIZE - offset);
        chunk_buffer[0] = 0x01;
        memcpy(chunk_buffer + 1, output_grid + offset, chunk);
        bluetooth_send_data(chunk_buffer, chunk + 1);
        offset += chunk;
        nrfx_systick_delay_ms(20);
        reload_watchdog(NULL, NULL);
    }

    /* ===== Step 11: Send end marker ===== */
    nrfx_systick_delay_ms(100);
    uint8_t end_marker[5] = {0x01, 0xFF, 0xFF, 0x00, 0x00};
    bluetooth_send_data(end_marker, 5);

    free(chunk_buffer);

    /* Return total bytes sent (image + predictions) */
    lua_pushinteger(L, total_bytes + FOMO_OUTPUT_SIZE);
    return 1;
}

/**
 * Fast object detection - skips camera wake and autoexposure.
 * Call frame.camera.power_save(false) and frame.camera.auto() before first use.
 */
static int lua_experiment_run_object_detection_fast(lua_State *L)
{
    const uint16_t CAPTURE_SIZE = 720;
    const uint16_t SCALED_SIZE = 90;
    const uint16_t OUTPUT_SIZE = 64;
    const size_t MAX_JPEG_SIZE = 25 * 1024;
    const size_t CHUNK_SIZE = 200;
    const size_t READ_CHUNK_SIZE = 512;

    size_t jpeg_size = 0;
    uint16_t actual_width, actual_height;
    int result;

    if (!fomo_is_initialized()) {
        luaL_error(L, "FOMO model not initialized");
        return 0;
    }

    uint8_t *jpeg_buffer = malloc(MAX_JPEG_SIZE);
    uint8_t *temp_buffer = malloc(SCALED_SIZE * SCALED_SIZE);
    uint8_t *gray_buffer = malloc(OUTPUT_SIZE * OUTPUT_SIZE);
    if (!jpeg_buffer || !temp_buffer || !gray_buffer) {
        if (jpeg_buffer) free(jpeg_buffer);
        if (temp_buffer) free(temp_buffer);
        if (gray_buffer) free(gray_buffer);
        luaL_error(L, "allocation failed");
        return 0;
    }

    memset(jpeg_buffer, 0, MAX_JPEG_SIZE);
    memset(temp_buffer, 0, SCALED_SIZE * SCALED_SIZE);
    memset(gray_buffer, 0, OUTPUT_SIZE * OUTPUT_SIZE);

#ifdef DEV_KIT_BUILD
    free(jpeg_buffer);
    result = jpeg_decode_grayscale_scaled(test_jpeg_data, test_jpeg_size,
                                           temp_buffer, SCALED_SIZE, SCALED_SIZE,
                                           &actual_width, &actual_height,
                                           3, false);
    if (result != 0) {
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "decode failed: %d", result);
        return 0;
    }

    LOG("DEV_KIT: decoded %dx%d, downscaling to %dx%d", actual_width, actual_height, OUTPUT_SIZE, OUTPUT_SIZE);

    {
        const float scale = (float)SCALED_SIZE / (float)OUTPUT_SIZE;
        for (int dy = 0; dy < OUTPUT_SIZE; dy++) {
            for (int dx = 0; dx < OUTPUT_SIZE; dx++) {
                float sx = dx * scale;
                float sy = dy * scale;
                int x0 = (int)sx;
                int y0 = (int)sy;
                int x1 = (x0 + 1 < SCALED_SIZE) ? x0 + 1 : x0;
                int y1 = (y0 + 1 < SCALED_SIZE) ? y0 + 1 : y0;
                float fx = sx - x0;
                float fy = sy - y0;
                float v00 = temp_buffer[y0 * SCALED_SIZE + x0];
                float v10 = temp_buffer[y0 * SCALED_SIZE + x1];
                float v01 = temp_buffer[y1 * SCALED_SIZE + x0];
                float v11 = temp_buffer[y1 * SCALED_SIZE + x1];
                float v = v00 * (1-fx) * (1-fy) + v10 * fx * (1-fy) +
                          v01 * (1-fx) * fy + v11 * fx * fy;
                gray_buffer[dy * OUTPUT_SIZE + dx] = (uint8_t)(v + 0.5f);
            }
        }
    }
    free(temp_buffer);
    actual_width = OUTPUT_SIZE;
    actual_height = OUTPUT_SIZE;
#else
    /* Fast path: Skip camera wake (Step 0) and autoexposure (Step 1) */
    /* Caller must ensure camera is awake and auto-adjusted before calling */

    /* ===== Step 2: Capture image ===== */
    lua_getglobal(L, "frame");
    lua_getfield(L, -1, "camera");
    lua_getfield(L, -1, "capture");
    if (!lua_isfunction(L, -1)) {
        lua_pop(L, 3);
        free(jpeg_buffer);
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "frame.camera.capture not found");
        return 0;
    }
    lua_newtable(L);
    lua_pushinteger(L, CAPTURE_SIZE);
    lua_setfield(L, -2, "resolution");
    lua_pushstring(L, "MEDIUM");
    lua_setfield(L, -2, "quality");
    if (lua_pcall(L, 1, 0, 0) != LUA_OK) {
        const char *err = lua_tostring(L, -1);
        lua_pop(L, 3);
        free(jpeg_buffer);
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "camera.capture failed: %s", err);
        return 0;
    }
    lua_pop(L, 2);

    /* ===== Step 3: Wait for image to be ready ===== */
    uint32_t timeout = 1000000;
    uint32_t wdt_counter = 0;
    bool ready = false;
    while (timeout-- && !ready) {
        lua_getglobal(L, "frame");
        lua_getfield(L, -1, "camera");
        lua_getfield(L, -1, "image_ready");
        if (lua_pcall(L, 0, 1, 0) != LUA_OK) {
            const char *err = lua_tostring(L, -1);
            lua_pop(L, 3);
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "camera.image_ready failed: %s", err);
            return 0;
        }
        ready = lua_toboolean(L, -1);
        lua_pop(L, 3);
        if (!ready) {
            nrfx_systick_delay_us(10);
            if (++wdt_counter >= 10000) {
                reload_watchdog(NULL, NULL);
                wdt_counter = 0;
            }
        }
    }

    if (!ready) {
        free(jpeg_buffer);
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "capture timeout");
        return 0;
    }

    /* ===== Step 4: Read JPEG data ===== */
    jpeg_size = 0;
    while (jpeg_size < MAX_JPEG_SIZE) {
        lua_getglobal(L, "frame");
        lua_getfield(L, -1, "camera");
        lua_getfield(L, -1, "read");
        lua_pushinteger(L, READ_CHUNK_SIZE);
        if (lua_pcall(L, 1, 1, 0) != LUA_OK) {
            const char *err = lua_tostring(L, -1);
            lua_pop(L, 3);
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "camera.read failed: %s", err);
            return 0;
        }

        if (lua_isnil(L, -1)) {
            lua_pop(L, 3);
            break;
        }

        size_t chunk_len;
        const char *chunk = lua_tolstring(L, -1, &chunk_len);
        if (jpeg_size + chunk_len > MAX_JPEG_SIZE) {
            lua_pop(L, 3);
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "JPEG too large");
            return 0;
        }
        memcpy(jpeg_buffer + jpeg_size, chunk, chunk_len);
        jpeg_size += chunk_len;
        lua_pop(L, 3);
        reload_watchdog(NULL, NULL);
    }

    if (jpeg_size == 0) {
        free(jpeg_buffer);
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "no JPEG data received");
        return 0;
    }

    /* ===== Step 5: Decode JPEG to grayscale with 1/8 scaling ===== */
    reload_watchdog(NULL, NULL);
    result = jpeg_decode_grayscale_scaled(jpeg_buffer, jpeg_size,
                                           temp_buffer, SCALED_SIZE, SCALED_SIZE,
                                           &actual_width, &actual_height,
                                           3, false);
    free(jpeg_buffer);

    if (result != 0) {
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "decode failed: %d", result);
        return 0;
    }

    LOG("Decoded %dx%d, downscaling to %dx%d with 90 CCW rotation",
        actual_width, actual_height, OUTPUT_SIZE, OUTPUT_SIZE);

    /* ===== Step 6: Downscale 90x90 to 64x64 with 90° CCW rotation ===== */
    reload_watchdog(NULL, NULL);
    {
        const float scale = (float)SCALED_SIZE / (float)OUTPUT_SIZE;
        for (int dy = 0; dy < OUTPUT_SIZE; dy++) {
            for (int dx = 0; dx < OUTPUT_SIZE; dx++) {
                float sx = dx * scale;
                float sy = dy * scale;
                int x0 = (int)sx;
                int y0 = (int)sy;
                int x1 = (x0 + 1 < SCALED_SIZE) ? x0 + 1 : x0;
                int y1 = (y0 + 1 < SCALED_SIZE) ? y0 + 1 : y0;
                float fx = sx - x0;
                float fy = sy - y0;
                float v00 = temp_buffer[y0 * SCALED_SIZE + x0];
                float v10 = temp_buffer[y0 * SCALED_SIZE + x1];
                float v01 = temp_buffer[y1 * SCALED_SIZE + x0];
                float v11 = temp_buffer[y1 * SCALED_SIZE + x1];
                float v = v00 * (1-fx) * (1-fy) + v10 * fx * (1-fy) +
                          v01 * (1-fx) * fy + v11 * fx * fy;
                int rx = dy;
                int ry = OUTPUT_SIZE - 1 - dx;
                gray_buffer[ry * OUTPUT_SIZE + rx] = (uint8_t)(v + 0.5f);
            }
        }
    }
    free(temp_buffer);
    actual_width = OUTPUT_SIZE;
    actual_height = OUTPUT_SIZE;
#endif /* !DEV_KIT_BUILD */

    /* ===== Step 7: Run FOMO inference ===== */
    reload_watchdog(NULL, NULL);
    int8_t output_grid[FOMO_OUTPUT_SIZE];

    tflm_status_t infer_status = fomo_infer(gray_buffer, output_grid);
    if (infer_status != TFLM_OK) {
        free(gray_buffer);
        luaL_error(L, "FOMO inference failed");
        return 0;
    }

    LOG("FOMO inference complete");

    /* ===== Step 7.5: Display detection overlay on Frame ===== */
    draw_detection_overlay(output_grid);
    reload_watchdog(NULL, NULL);

    /* ===== Step 8: Send image data via Bluetooth ===== */
    size_t total_bytes = actual_width * actual_height;
    size_t offset = 0;

    uint8_t *chunk_buffer = malloc(CHUNK_SIZE + 1);
    if (!chunk_buffer) {
        free(gray_buffer);
        luaL_error(L, "chunk allocation failed");
        return 0;
    }
    chunk_buffer[0] = 0x01;

    while (offset < total_bytes) {
        size_t chunk = (total_bytes - offset > CHUNK_SIZE) ? CHUNK_SIZE : (total_bytes - offset);
        memcpy(chunk_buffer + 1, gray_buffer + offset, chunk);
        bluetooth_send_data(chunk_buffer, chunk + 1);
        offset += chunk;
        nrfx_systick_delay_ms(20);
        reload_watchdog(NULL, NULL);
    }

    free(gray_buffer);

    /* ===== Step 9: Send separator ===== */
    nrfx_systick_delay_ms(50);
    uint8_t separator[3] = {0x01, 0xFE, 0xFE};
    bluetooth_send_data(separator, 3);

    /* ===== Step 10: Send predictions ===== */
    nrfx_systick_delay_ms(50);
    offset = 0;
    while (offset < FOMO_OUTPUT_SIZE) {
        size_t chunk = (FOMO_OUTPUT_SIZE - offset > CHUNK_SIZE) ? CHUNK_SIZE : (FOMO_OUTPUT_SIZE - offset);
        chunk_buffer[0] = 0x01;
        memcpy(chunk_buffer + 1, output_grid + offset, chunk);
        bluetooth_send_data(chunk_buffer, chunk + 1);
        offset += chunk;
        nrfx_systick_delay_ms(20);
        reload_watchdog(NULL, NULL);
    }

    /* ===== Step 11: Send end marker ===== */
    nrfx_systick_delay_ms(100);
    uint8_t end_marker[5] = {0x01, 0xFF, 0xFF, 0x00, 0x00};
    bluetooth_send_data(end_marker, 5);

    free(chunk_buffer);

    lua_pushinteger(L, total_bytes + FOMO_OUTPUT_SIZE);
    return 1;
}

/**
 * Draw simple text overlay for person detection result.
 * Displays colored indicator for PERSON (green) or NO PERSON (red)
 *
 * @param is_person True if person detected, false otherwise
 * @param person_score Confidence score for person class
 */
static void draw_person_detection_overlay(bool is_person, int8_t person_score)
{
    const uint16_t DISPLAY_W = 640;
    const uint16_t DISPLAY_H = 400;

    /* Color indices */
    const uint8_t PERSON_COLOR = 10;     /* GREEN for person */
    const uint8_t NO_PERSON_COLOR = 3;   /* RED for no person */

    /* Rectangle indicator: 100x60 filled block */
    static const uint8_t block_sprite[750] = {  /* 100x60 = 6000 bits = 750 bytes, all 0xFF */
        [0 ... 749] = 0xFF
    };

    /* Position: center of display */
    int16_t px = (DISPLAY_W - 100) / 2;
    int16_t py = (DISPLAY_H - 60) / 2;

    uint8_t color = is_person ? PERSON_COLOR : NO_PERSON_COLOR;

    /* Draw indicator block */
    uint8_t meta[8] = {
        (uint8_t)(px >> 8), (uint8_t)(px & 0xFF),
        (uint8_t)(py >> 8), (uint8_t)(py & 0xFF),
        0, 100,  /* width = 100 */
        2,       /* 2 colors (1-bit) */
        color
    };

    uint8_t *payload = malloc(8 + 750);
    if (payload) {
        memcpy(payload, meta, 8);
        memcpy(payload + 8, block_sprite, 750);
        spi_write(FPGA, 0x12, payload, 8 + 750);
        free(payload);
    }

    /* Swap frame buffers to show */
    spi_write(FPGA, 0x14, NULL, 0);
}

/**
 * Run person detection on camera image.
 *
 * Image pipeline: 720x720 JPEG -> scale=3 (90x90) -> upscale to 96x96
 * Output: Display PERSON (green) or NO PERSON (red) overlay
 *
 * Protocol:
 *   [IMAGE DATA]     9216 bytes (96x96 grayscale)
 *   [SEPARATOR]      0x01 0xFE 0xFE
 *   [PREDICTIONS]    2 bytes (not_person_score, person_score)
 *   [END MARKER]     0x01 0xFF 0xFF 0x00 0x00
 */
static int lua_experiment_run_person_detection(lua_State *L)
{
    const uint16_t CAPTURE_SIZE = 720;
    const uint16_t SCALED_SIZE = 90;       /* After TJpgDec scale=3 (720/8=90) */
    const uint16_t OUTPUT_SIZE = 96;       /* ML input size (96x96) */
    const size_t MAX_JPEG_SIZE = 25 * 1024;
    const size_t CHUNK_SIZE = 200;
    const size_t READ_CHUNK_SIZE = 512;

    size_t jpeg_size = 0;
    uint16_t actual_width, actual_height;
    int result;

    /* Check if person detect model is initialized */
    if (!person_detect_is_initialized()) {
        luaL_error(L, "Person detect model not initialized");
        return 0;
    }

    /* Allocate buffers */
    uint8_t *jpeg_buffer = malloc(MAX_JPEG_SIZE);
    uint8_t *temp_buffer = malloc(SCALED_SIZE * SCALED_SIZE);  /* 90x90 = 8KB */
    uint8_t *gray_buffer = malloc(OUTPUT_SIZE * OUTPUT_SIZE);  /* 96x96 = 9KB */
    if (!jpeg_buffer || !temp_buffer || !gray_buffer) {
        if (jpeg_buffer) free(jpeg_buffer);
        if (temp_buffer) free(temp_buffer);
        if (gray_buffer) free(gray_buffer);
        luaL_error(L, "allocation failed");
        return 0;
    }

    memset(temp_buffer, 0, SCALED_SIZE * SCALED_SIZE);
    memset(gray_buffer, 0, OUTPUT_SIZE * OUTPUT_SIZE);

#ifdef DEV_KIT_BUILD
    /* DEV_KIT: Use hardcoded test JPEG data instead of camera */
    free(jpeg_buffer);  /* Not needed for test path */
    LOG("DEV_KIT: Using hardcoded test JPEG data (%u bytes)", test_jpeg_size);

    /* Decode test JPEG to 90x90 grayscale */
    reload_watchdog(NULL, NULL);
    result = jpeg_decode_grayscale_scaled(test_jpeg_data, test_jpeg_size,
                                           temp_buffer, SCALED_SIZE, SCALED_SIZE,
                                           &actual_width, &actual_height,
                                           3, false);  /* scale=3 (1/8), no rotation */
    if (result != 0) {
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "decode failed: %d", result);
        return 0;
    }
    LOG("DEV_KIT: decoded %dx%d", actual_width, actual_height);

#else /* !DEV_KIT_BUILD */
    memset(jpeg_buffer, 0, MAX_JPEG_SIZE);

    /* ===== Step 1: Wake up camera ===== */
    lua_getglobal(L, "frame");
    lua_getfield(L, -1, "camera");
    lua_getfield(L, -1, "power_save");
    if (lua_isfunction(L, -1)) {
        lua_pushboolean(L, 0);  /* power_save(false) */
        if (lua_pcall(L, 1, 0, 0) != LUA_OK) {
            lua_pop(L, 3);
        }
    } else {
        lua_pop(L, 1);
    }
    lua_pop(L, 2);
    nrfx_systick_delay_ms(100);

    /* ===== Step 2: Auto-adjust camera (5 iterations) ===== */
    for (int i = 0; i < 5; i++) {
        lua_getglobal(L, "frame");
        lua_getfield(L, -1, "camera");
        lua_getfield(L, -1, "auto");
        if (!lua_isfunction(L, -1)) {
            lua_pop(L, 3);
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "camera.auto not found");
            return 0;
        }
        lua_newtable(L);
        if (lua_pcall(L, 1, 1, 0) != LUA_OK) {
            lua_pop(L, 3);
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "camera.auto failed");
            return 0;
        }
        lua_pop(L, 3);
        nrfx_systick_delay_ms(100);
        reload_watchdog(NULL, NULL);
    }

    /* ===== Step 3: Capture image ===== */
    lua_getglobal(L, "frame");
    lua_getfield(L, -1, "camera");
    lua_getfield(L, -1, "capture");
    if (!lua_isfunction(L, -1)) {
        lua_pop(L, 3);
        free(jpeg_buffer);
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "camera.capture not found");
        return 0;
    }
    lua_newtable(L);
    lua_pushinteger(L, CAPTURE_SIZE);
    lua_setfield(L, -2, "resolution");
    lua_pushstring(L, "MEDIUM");
    lua_setfield(L, -2, "quality");
    if (lua_pcall(L, 1, 0, 0) != LUA_OK) {
        lua_pop(L, 3);
        free(jpeg_buffer);
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "capture failed");
        return 0;
    }
    lua_pop(L, 2);

    /* ===== Step 4: Wait for image ready ===== */
    uint32_t timeout = 1000000;
    bool ready = false;
    while (timeout-- && !ready) {
        lua_getglobal(L, "frame");
        lua_getfield(L, -1, "camera");
        lua_getfield(L, -1, "image_ready");
        if (lua_pcall(L, 0, 1, 0) != LUA_OK) {
            lua_pop(L, 3);
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "image_ready failed");
            return 0;
        }
        ready = lua_toboolean(L, -1);
        lua_pop(L, 3);
        if (!ready) {
            nrfx_systick_delay_us(10);
        }
        reload_watchdog(NULL, NULL);
    }

    if (!ready) {
        free(jpeg_buffer);
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "capture timeout");
        return 0;
    }

    /* ===== Step 5: Read JPEG data ===== */
    jpeg_size = 0;
    while (jpeg_size < MAX_JPEG_SIZE) {
        lua_getglobal(L, "frame");
        lua_getfield(L, -1, "camera");
        lua_getfield(L, -1, "read");
        lua_pushinteger(L, READ_CHUNK_SIZE);
        if (lua_pcall(L, 1, 1, 0) != LUA_OK) {
            lua_pop(L, 3);
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "read failed");
            return 0;
        }

        if (lua_isnil(L, -1)) {
            lua_pop(L, 3);
            break;
        }

        size_t chunk_len;
        const char *chunk = lua_tolstring(L, -1, &chunk_len);
        memcpy(jpeg_buffer + jpeg_size, chunk, chunk_len);
        jpeg_size += chunk_len;
        lua_pop(L, 3);
        reload_watchdog(NULL, NULL);
    }

    LOG("Person detect: JPEG size = %u bytes", jpeg_size);

    /* ===== Step 6: Decode JPEG to 90x90 grayscale ===== */
    reload_watchdog(NULL, NULL);
    result = jpeg_decode_grayscale_scaled(jpeg_buffer, jpeg_size,
                                           temp_buffer, SCALED_SIZE, SCALED_SIZE,
                                           &actual_width, &actual_height,
                                           3, false);  /* scale=3 (1/8), no rotation */
    free(jpeg_buffer);

    if (result != 0) {
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "decode failed: %d", result);
        return 0;
    }

    LOG("Person detect: decoded %dx%d, UPSCALING to %dx%d", actual_width, actual_height, OUTPUT_SIZE, OUTPUT_SIZE);
#endif /* !DEV_KIT_BUILD */

    /* ===== Step 7: UPSCALE 90x90 to 96x96 with 90° CCW rotation ===== */
    reload_watchdog(NULL, NULL);
    {
        const float scale = (float)SCALED_SIZE / (float)OUTPUT_SIZE;  /* 90/96 = 0.9375 */
        for (int dy = 0; dy < OUTPUT_SIZE; dy++) {
            for (int dx = 0; dx < OUTPUT_SIZE; dx++) {
                float sx = dx * scale;
                float sy = dy * scale;

                int x0 = (int)sx;
                int y0 = (int)sy;
                int x1 = (x0 + 1 < SCALED_SIZE) ? x0 + 1 : x0;
                int y1 = (y0 + 1 < SCALED_SIZE) ? y0 + 1 : y0;

                float fx = sx - x0;
                float fy = sy - y0;

                float v00 = temp_buffer[y0 * SCALED_SIZE + x0];
                float v10 = temp_buffer[y0 * SCALED_SIZE + x1];
                float v01 = temp_buffer[y1 * SCALED_SIZE + x0];
                float v11 = temp_buffer[y1 * SCALED_SIZE + x1];

                float v = v00 * (1-fx) * (1-fy) + v10 * fx * (1-fy) +
                          v01 * (1-fx) * fy + v11 * fx * fy;

                /* Apply 90° CCW rotation: (dx, dy) -> (dy, OUTPUT_SIZE-1-dx) */
                int rx = dy;
                int ry = OUTPUT_SIZE - 1 - dx;
                gray_buffer[ry * OUTPUT_SIZE + rx] = (uint8_t)(v + 0.5f);
            }
        }
    }
    free(temp_buffer);

    /* ===== Step 8: Run person detection inference ===== */
    reload_watchdog(NULL, NULL);
    int8_t output_scores[PERSON_OUTPUT_SIZE];  /* 2 bytes */

    tflm_status_t infer_status = person_detect_infer(gray_buffer, output_scores);
    if (infer_status != TFLM_OK) {
        free(gray_buffer);
        luaL_error(L, "Person detect inference failed");
        return 0;
    }

    int8_t not_person_score = output_scores[PERSON_NOT_PERSON_INDEX];
    int8_t person_score = output_scores[PERSON_PERSON_INDEX];
    bool is_person = (person_score > not_person_score);

    LOG("Person detect: not_person=%d, person=%d, result=%s",
        not_person_score, person_score, is_person ? "PERSON" : "NO PERSON");

    /* ===== Step 9: Display overlay ===== */
    draw_person_detection_overlay(is_person, person_score);
    reload_watchdog(NULL, NULL);

    /* ===== Step 10: Send image data via Bluetooth ===== */
    size_t total_bytes = OUTPUT_SIZE * OUTPUT_SIZE;  /* 9216 */
    size_t offset = 0;

    uint8_t *chunk_buffer = malloc(CHUNK_SIZE + 1);
    if (!chunk_buffer) {
        free(gray_buffer);
        luaL_error(L, "chunk allocation failed");
        return 0;
    }
    chunk_buffer[0] = 0x01;  /* Data flag */

    while (offset < total_bytes) {
        size_t chunk = (total_bytes - offset > CHUNK_SIZE) ? CHUNK_SIZE : (total_bytes - offset);
        memcpy(chunk_buffer + 1, gray_buffer + offset, chunk);
        bluetooth_send_data(chunk_buffer, chunk + 1);
        offset += chunk;
        nrfx_systick_delay_ms(20);
        reload_watchdog(NULL, NULL);
    }

    free(gray_buffer);

    /* ===== Step 11: Send separator ===== */
    nrfx_systick_delay_ms(50);
    uint8_t separator[3] = {0x01, 0xFE, 0xFE};
    bluetooth_send_data(separator, 3);

    /* ===== Step 12: Send predictions (2 bytes) ===== */
    nrfx_systick_delay_ms(50);
    chunk_buffer[0] = 0x01;
    memcpy(chunk_buffer + 1, output_scores, PERSON_OUTPUT_SIZE);
    bluetooth_send_data(chunk_buffer, PERSON_OUTPUT_SIZE + 1);

    /* ===== Step 13: Send end marker ===== */
    nrfx_systick_delay_ms(100);
    uint8_t end_marker[5] = {0x01, 0xFF, 0xFF, 0x00, 0x00};
    bluetooth_send_data(end_marker, 5);

    free(chunk_buffer);

    lua_pushinteger(L, total_bytes + PERSON_OUTPUT_SIZE);
    return 1;
}

/**
 * Run person detection benchmark - local inference without Bluetooth transmission
 * Lua: result = frame.experiment.run_person_detection_benchmark(iterations)
 * Returns: { iterations, person_detections, total_time_ms, avg_time_ms }
 */
static int lua_experiment_run_person_detection_benchmark(lua_State *L)
{
    const uint16_t SCALED_SIZE = 90;       /* After TJpgDec scale=3 (720/8=90) */
    const uint16_t OUTPUT_SIZE = 96;       /* ML input size (96x96) */

    uint16_t actual_width, actual_height;
    int result;

    /* Get iterations parameter */
    lua_Integer iterations = luaL_checkinteger(L, 1);
    if (iterations < 1 || iterations > 1000) {
        luaL_error(L, "iterations must be between 1 and 1000");
        return 0;
    }

    /* Check if person detect model is initialized */
    if (!person_detect_is_initialized()) {
        luaL_error(L, "Person detect model not initialized");
        return 0;
    }

    /* Allocate buffers - reused across all iterations */
    uint8_t *temp_buffer = malloc(SCALED_SIZE * SCALED_SIZE);  /* 90x90 = 8KB */
    uint8_t *gray_buffer = malloc(OUTPUT_SIZE * OUTPUT_SIZE);  /* 96x96 = 9KB */
    if (!temp_buffer || !gray_buffer) {
        if (temp_buffer) free(temp_buffer);
        if (gray_buffer) free(gray_buffer);
        luaL_error(L, "allocation failed");
        return 0;
    }

#ifndef DEV_KIT_BUILD
    const uint16_t CAPTURE_SIZE = 720;
    const size_t MAX_JPEG_SIZE = 25 * 1024;
    const size_t READ_CHUNK_SIZE = 512;
    size_t jpeg_size = 0;

    uint8_t *jpeg_buffer = malloc(MAX_JPEG_SIZE);
    if (!jpeg_buffer) {
        free(temp_buffer);
        free(gray_buffer);
        luaL_error(L, "JPEG allocation failed");
        return 0;
    }

    /* ===== Initialize camera ONCE before benchmark loop ===== */
    lua_getglobal(L, "frame");
    lua_getfield(L, -1, "camera");
    lua_getfield(L, -1, "power_save");
    if (lua_isfunction(L, -1)) {
        lua_pushboolean(L, 0);  /* power_save(false) */
        if (lua_pcall(L, 1, 0, 0) != LUA_OK) {
            lua_pop(L, 3);
        }
    } else {
        lua_pop(L, 1);
    }
    lua_pop(L, 2);
    nrfx_systick_delay_ms(100);

    /* Auto-adjust camera (5 iterations) */
    for (int i = 0; i < 5; i++) {
        lua_getglobal(L, "frame");
        lua_getfield(L, -1, "camera");
        lua_getfield(L, -1, "auto");
        if (!lua_isfunction(L, -1)) {
            lua_pop(L, 3);
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "camera.auto not found");
            return 0;
        }
        lua_newtable(L);
        if (lua_pcall(L, 1, 1, 0) != LUA_OK) {
            lua_pop(L, 3);
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "camera.auto failed");
            return 0;
        }
        lua_pop(L, 3);
        nrfx_systick_delay_ms(100);
        reload_watchdog(NULL, NULL);
    }
    LOG("Benchmark: camera initialized");
#endif

    int person_count = 0;

    /* Enable DWT cycle counter for precise timing */
    CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk;
    DWT->CYCCNT = 0;
    DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;

    uint32_t start_cycles = DWT->CYCCNT;

    /* ===== Main benchmark loop ===== */
    for (int iter = 0; iter < iterations; iter++) {
        reload_watchdog(NULL, NULL);

        memset(temp_buffer, 0, SCALED_SIZE * SCALED_SIZE);
        memset(gray_buffer, 0, OUTPUT_SIZE * OUTPUT_SIZE);

#ifdef DEV_KIT_BUILD
        /* DEV_KIT: Use hardcoded test JPEG data (same image each iteration) */
        result = jpeg_decode_grayscale_scaled(test_jpeg_data, test_jpeg_size,
                                               temp_buffer, SCALED_SIZE, SCALED_SIZE,
                                               &actual_width, &actual_height,
                                               3, false);  /* scale=3 (1/8), no rotation */
        if (result != 0) {
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "decode failed: %d", result);
            return 0;
        }
#else
        /* Capture new image each iteration */
        memset(jpeg_buffer, 0, MAX_JPEG_SIZE);

        /* Capture image */
        lua_getglobal(L, "frame");
        lua_getfield(L, -1, "camera");
        lua_getfield(L, -1, "capture");
        if (!lua_isfunction(L, -1)) {
            lua_pop(L, 3);
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "camera.capture not found");
            return 0;
        }
        lua_newtable(L);
        lua_pushinteger(L, CAPTURE_SIZE);
        lua_setfield(L, -2, "resolution");
        lua_pushstring(L, "MEDIUM");
        lua_setfield(L, -2, "quality");
        if (lua_pcall(L, 1, 0, 0) != LUA_OK) {
            lua_pop(L, 3);
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "capture failed");
            return 0;
        }
        lua_pop(L, 2);

        /* Wait for image ready */
        uint32_t timeout = 1000000;
        bool ready = false;
        while (timeout-- && !ready) {
            lua_getglobal(L, "frame");
            lua_getfield(L, -1, "camera");
            lua_getfield(L, -1, "image_ready");
            if (lua_pcall(L, 0, 1, 0) != LUA_OK) {
                lua_pop(L, 3);
                free(jpeg_buffer);
                free(temp_buffer);
                free(gray_buffer);
                luaL_error(L, "image_ready failed");
                return 0;
            }
            ready = lua_toboolean(L, -1);
            lua_pop(L, 3);
            if (!ready) {
                nrfx_systick_delay_us(10);
            }
            reload_watchdog(NULL, NULL);
        }

        if (!ready) {
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "capture timeout");
            return 0;
        }

        /* Read JPEG data */
        jpeg_size = 0;
        while (jpeg_size < MAX_JPEG_SIZE) {
            lua_getglobal(L, "frame");
            lua_getfield(L, -1, "camera");
            lua_getfield(L, -1, "read");
            lua_pushinteger(L, READ_CHUNK_SIZE);
            if (lua_pcall(L, 1, 1, 0) != LUA_OK) {
                lua_pop(L, 3);
                free(jpeg_buffer);
                free(temp_buffer);
                free(gray_buffer);
                luaL_error(L, "read failed");
                return 0;
            }

            if (lua_isnil(L, -1)) {
                lua_pop(L, 3);
                break;
            }

            size_t chunk_len;
            const char *chunk = lua_tolstring(L, -1, &chunk_len);
            memcpy(jpeg_buffer + jpeg_size, chunk, chunk_len);
            jpeg_size += chunk_len;
            lua_pop(L, 3);
            reload_watchdog(NULL, NULL);
        }

        /* Decode JPEG to 90x90 grayscale */
        reload_watchdog(NULL, NULL);
        result = jpeg_decode_grayscale_scaled(jpeg_buffer, jpeg_size,
                                               temp_buffer, SCALED_SIZE, SCALED_SIZE,
                                               &actual_width, &actual_height,
                                               3, false);  /* scale=3 (1/8), no rotation */
        if (result != 0) {
            free(jpeg_buffer);
            free(temp_buffer);
            free(gray_buffer);
            luaL_error(L, "decode failed: %d", result);
            return 0;
        }
#endif

        /* Upscale 90x90 to 96x96 with 90° CCW rotation */
        reload_watchdog(NULL, NULL);
        {
            const float scale = (float)SCALED_SIZE / (float)OUTPUT_SIZE;  /* 90/96 = 0.9375 */
            for (int dy = 0; dy < OUTPUT_SIZE; dy++) {
                for (int dx = 0; dx < OUTPUT_SIZE; dx++) {
                    float sx = dx * scale;
                    float sy = dy * scale;

                    int x0 = (int)sx;
                    int y0 = (int)sy;
                    int x1 = (x0 + 1 < SCALED_SIZE) ? x0 + 1 : x0;
                    int y1 = (y0 + 1 < SCALED_SIZE) ? y0 + 1 : y0;

                    float fx = sx - x0;
                    float fy = sy - y0;

                    float v00 = temp_buffer[y0 * SCALED_SIZE + x0];
                    float v10 = temp_buffer[y0 * SCALED_SIZE + x1];
                    float v01 = temp_buffer[y1 * SCALED_SIZE + x0];
                    float v11 = temp_buffer[y1 * SCALED_SIZE + x1];

                    float v = v00 * (1-fx) * (1-fy) + v10 * fx * (1-fy) +
                              v01 * (1-fx) * fy + v11 * fx * fy;

                    /* Apply 90° CCW rotation: (dx, dy) -> (dy, OUTPUT_SIZE-1-dx) */
                    int rx = dy;
                    int ry = OUTPUT_SIZE - 1 - dx;
                    gray_buffer[ry * OUTPUT_SIZE + rx] = (uint8_t)(v + 0.5f);
                }
            }
        }

        /* Run person detection inference */
        reload_watchdog(NULL, NULL);
        int8_t output_scores[PERSON_OUTPUT_SIZE];

        tflm_status_t infer_status = person_detect_infer(gray_buffer, output_scores);
        if (infer_status != TFLM_OK) {
            free(temp_buffer);
            free(gray_buffer);
#ifndef DEV_KIT_BUILD
            free(jpeg_buffer);
#endif
            luaL_error(L, "Person detect inference failed");
            return 0;
        }

        int8_t person_score = output_scores[PERSON_PERSON_INDEX];
        int8_t not_person_score = output_scores[PERSON_NOT_PERSON_INDEX];
        bool is_person = (person_score > not_person_score);

        if (is_person) {
            person_count++;
        }

        /* Update display every iteration */
        draw_person_detection_overlay(is_person, person_score);
        reload_watchdog(NULL, NULL);

        /* Log progress every 10 iterations */
        if ((iter + 1) % 10 == 0) {
            LOG("Benchmark: %d/%d iterations", iter + 1, (int)iterations);
        }
    }

    uint32_t end_cycles = DWT->CYCCNT;

    /* Calculate timing - CPU runs at 64MHz */
    uint32_t elapsed_cycles = end_cycles - start_cycles;
    uint32_t total_ms = elapsed_cycles / 64000;  /* 64MHz = 64000 cycles/ms */
    uint32_t avg_ms = total_ms / (uint32_t)iterations;

    /* Cleanup */
    free(temp_buffer);
    free(gray_buffer);
#ifndef DEV_KIT_BUILD
    free(jpeg_buffer);
#endif

    LOG("Benchmark complete: %d iterations, %d detections, %lu ms total, %lu ms avg",
        (int)iterations, person_count, total_ms, avg_ms);

    /* Return results table */
    lua_newtable(L);
    lua_pushinteger(L, iterations);
    lua_setfield(L, -2, "iterations");
    lua_pushinteger(L, person_count);
    lua_setfield(L, -2, "person_detections");
    lua_pushinteger(L, total_ms);
    lua_setfield(L, -2, "total_time_ms");
    lua_pushinteger(L, avg_ms);
    lua_setfield(L, -2, "avg_time_ms");

    return 1;
}

/**
 * Experiments are callebale as 'frame.experiment.hello_world' for example
 */
void lua_open_experiment_library(lua_State *L)
{
    lua_getglobal(L, "frame");

    // New table to have nested commands for experiments
    lua_newtable(L);

    lua_pushcfunction(L, lua_experiment_send_grayscale);
    lua_setfield(L, -2, "send_grayscale");

    lua_pushcfunction(L, lua_experiment_run_object_detection);
    lua_setfield(L, -2, "run_object_detection_model");

    lua_pushcfunction(L, lua_experiment_run_object_detection_fast);
    lua_setfield(L, -2, "run_object_detection_fast");

    lua_pushcfunction(L, lua_experiment_run_person_detection);
    lua_setfield(L, -2, "run_person_detection");

    lua_pushcfunction(L, lua_experiment_run_person_detection_benchmark);
    lua_setfield(L, -2, "run_person_detection_benchmark");

    lua_setfield(L, -2, "experiment");

    lua_pop(L, 1);
}